"""Media-generation tools (Part 2 — media GENERATED BY the model).

`generate_image` calls the configured provider, stores the result via file_store
(as an unassigned 'chat_message'/0 file — chat_service binds it to the assistant
message after the turn, exactly like a user upload in reverse), and publishes an
`artifact` event on the conversation bus so the web renders it live. The tool
returns only TEXT to the model (it can't emit binary), so the model narrates
while the user sees the image.

side_effect="write": external, paid, non-idempotent → flows through the normal
tool-policy / HITL machinery (a tenant can require approval or disable it).
"""
import asyncio
import logging

logger = logging.getLogger("agent.tools.media")


def _numeric_uid(user_context) -> int:
    """Best-effort platform integer user id from the UserContext for created_by."""
    raw = getattr(user_context, "user_id", None) if user_context else None
    if raw is None:
        return None
    s = str(raw)
    if s.isdigit():
        return int(s)
    # ids like 'user_5' → 5
    tail = s.rsplit("_", 1)[-1]
    return int(tail) if tail.isdigit() else None


class MediaGenerationTools:
    def __init__(self, db, image_provider, user_context=None):
        self._db = db
        self._image = image_provider
        self._uid = _numeric_uid(user_context)

    async def generate_image(self, prompt: str, size: str = None) -> str:
        if not prompt or not prompt.strip():
            return "generate_image needs a non-empty prompt."
        try:
            data, mime = await asyncio.to_thread(
                self._image.generate_image, prompt, size)
        except Exception as e:
            logger.warning("image generation failed: %s", e)
            return f"Image generation failed: {e}"

        from core.file_store import file_store, IMG
        from core.file_record import insert_file
        from core.tenant_context import current_tenant

        tenant = current_tenant().tenant_id
        ext = ".png" if "png" in (mime or "") else (".jpg" if "jpeg" in (mime or "") else ".png")
        written = file_store.write(
            file_type=IMG, extension=ext, data=data,
            associated_to="chat_message", associated_id=0,
            tenant_id=tenant, thumbnail=True)
        file_id = insert_file(
            self._db, file_type=IMG, associated_to="chat_message",
            associated_id=0, file_path=written["file_path"],
            file_name=f"generated{ext}", extension=ext, mime_type=mime,
            size_bytes=written["size_bytes"], created_by=self._uid)

        # Surface to the user live (assistant-side artifact).
        try:
            from agents.task_manager import current_conversation_bus
            bus = current_conversation_bus.get(None)
            if bus is not None:
                await bus.publish("artifact", {
                    "kind": "image", "file_id": file_id,
                    "media_type": mime, "prompt": prompt})
        except Exception:
            logger.debug("artifact publish failed", exc_info=True)

        return ("Generated the image and displayed it to the user. Add a short "
                "caption if useful; do not repeat the prompt verbatim.")
